// n8n Code Node – Mode: "Run Once for All Items"
// Verarbeitet eine Seite (max. 10.000 Zeilen) aus "Microsoft SQL – Seite" und gibt
// genau ein Item mit den fertigen CSV-Zeilen (ohne Header) zurück.
// Ersetzt die Nodes "Telefonnummer-Format-Bereinigung", "If", "Code in JavaScript",
// "Merge" und "Löschen Sonderfall-Attributs" aus "Google Ads - BB Customer Match List".
// Beide Skripte sind 1:1 übernommen. Nur die gleichnamigen Funktionen sind mit
// Stage1/Stage2 umbenannt, weil sich ihre Logik unterscheidet.

// ===== Stufe 1: "Telefonnummer-Format-Bereinigung" =====

const countryMap = {
  'deutschland': 'de',
  'germany': 'de',
  'schweiz': 'ch',
  'switzerland': 'ch',
  'suisse': 'ch',
  'österreich': 'at',
  'oesterreich': 'at',
  'austria': 'at'
};

const supportedPhoneCountries = ['de', 'ch', 'at'];

function cleanStringStage1(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function normalizeCountry(value) {
  const raw = cleanStringStage1(value);
  if (!raw) return '';

  const key = raw.toLowerCase();

  return countryMap[key] || raw;
}

function obviousFakePhoneStage1(digits) {
  if (!digits) return true;

  if (digits.length < 7 || digits.length > 15) return true;
  if (/^(\d)\1+$/.test(digits)) return true;
  if (/^(012345|123456|999999|000000)/.test(digits)) return true;

  const uniqueDigits = new Set(digits.split(''));
  if (digits.length >= 8 && uniqueDigits.size <= 2) return true;

  return false;
}

function normalizePhoneStage1(rawPhone, countryCode) {
  let phone = cleanStringStage1(rawPhone);

  if (!phone) {
    return {
      phone: '',
      sonderfall: false
    };
  }

  phone = phone.replace(/[^\d+]/g, '');

  if (!phone) {
    return {
      phone: '',
      sonderfall: false
    };
  }

  if (phone.startsWith('00')) {
    phone = '+' + phone.slice(2);
  }

  const isSupportedCountry = supportedPhoneCountries.includes(countryCode);

  if (countryCode === 'de') {
    if (phone.startsWith('+49')) {
      phone = phone.slice(1);
    } else if (phone.startsWith('49')) {
      // bleibt so
    } else if (phone.startsWith('0')) {
      phone = '49' + phone.slice(1);
    } else {
      return {
        phone: phone.replace(/\D/g, ''),
        sonderfall: true
      };
    }
  }

  if (countryCode === 'ch') {
    if (phone.startsWith('+41')) {
      phone = phone.slice(1);
    } else if (phone.startsWith('41')) {
      // bleibt so
    } else if (phone.startsWith('0')) {
      phone = '41' + phone.slice(1);
    } else {
      return {
        phone: phone.replace(/\D/g, ''),
        sonderfall: true
      };
    }
  }

  if (countryCode === 'at') {
    if (phone.startsWith('+43')) {
      phone = phone.slice(1);
    } else if (phone.startsWith('43')) {
      // bleibt so
    } else if (phone.startsWith('0')) {
      phone = '43' + phone.slice(1);
    } else {
      return {
        phone: phone.replace(/\D/g, ''),
        sonderfall: true
      };
    }
  }

  if (!isSupportedCountry) {
    let cleaned = phone.replace(/\+/g, '').replace(/\D/g, '');

    if (obviousFakePhoneStage1(cleaned)) {
      return {
        phone: '',
        sonderfall: false
      };
    }

    return {
      phone: cleaned,
      sonderfall: true
    };
  }

  phone = phone.replace(/\+/g, '').replace(/\D/g, '');

  if (obviousFakePhoneStage1(phone)) {
    return {
      phone: '',
      sonderfall: false
    };
  }

  return {
    phone,
    sonderfall: false
  };
}

// ===== Stufe 2: "Code in JavaScript" (nur für sonderfall === true) =====

function cleanStringStage2(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function obviousFakePhoneStage2(digits) {
  if (!digits) return true;
  if (digits.length < 7 || digits.length > 15) return true;
  if (/^(\d)\1+$/.test(digits)) return true;
  if (/^(012345|123456|999999|000000|123456789)/.test(digits)) return true;

  const uniqueDigits = new Set(digits.split(''));
  if (digits.length >= 8 && uniqueDigits.size <= 2) return true;

  return false;
}

function normalizePhoneStage2(rawPhone, country) {
  const original = cleanStringStage2(rawPhone);
  const countryCode = cleanStringStage2(country).toLowerCase();

  if (!original) return '';

  let phone = original.replace(/[^\d+]/g, '');

  if (!phone) return '';

  if (phone.startsWith('00')) {
    phone = '+' + phone.slice(2);
  }

  phone = phone.replace(/\+/g, '').replace(/\D/g, '');

  if (obviousFakePhoneStage2(phone)) return '';

  if (countryCode === 'de') {
    if (phone.startsWith('49')) return phone;
    if (phone.startsWith('0')) return '49' + phone.slice(1);

    // Deutsche Mobilnummer ohne führende 0, z. B. 17650335244
    if (/^1[5-7]\d{8,10}$/.test(phone)) {
      return '49' + phone;
    }

    // Keine sicher erkennbare deutsche Telefonnummer
    return '';
  }

  if (countryCode === 'at') {
    if (phone.startsWith('43')) return phone;
    if (phone.startsWith('0')) return '43' + phone.slice(1);

    // Österreichische Mobilnummer ohne führende 0, z. B. 6605239952
    if (/^6\d{7,11}$/.test(phone)) {
      return '43' + phone;
    }

    // Keine sicher erkennbare österreichische Telefonnummer
    return '';
  }

  if (countryCode === 'ch') {
    if (phone.startsWith('41')) return phone;
    if (phone.startsWith('0')) return '41' + phone.slice(1);

    // Schweizer Mobilnummer ohne führende 0, z. B. 791234567
    if (/^7\d{8}$/.test(phone)) {
      return '41' + phone;
    }

    // Keine sicher erkennbare Schweizer Telefonnummer
    return '';
  }

  return original;
}

// ===== Zeilen verarbeiten und als CSV serialisieren =====

const CSV_COLUMNS = ['Email', 'First Name', 'Last Name', 'Country', 'Zip', 'Phone'];

function csvField(value) {
  const text = value === null || value === undefined ? '' : String(value);
  if (/[",\r\n]/.test(text)) {
    return '"' + text.replace(/"/g, '""') + '"';
  }
  return text;
}

const zeilen = items.map(item => {
  const source = item.json;

  // Stufe 1
  const country = normalizeCountry(source.Land);
  const phoneResult = normalizePhoneStage1(source.Telefonnummer, country);

  const row = {
    Email: cleanStringStage1(source.EmailAdresse).toLowerCase(),
    'First Name': cleanStringStage1(source.Vorname),
    'Last Name': cleanStringStage1(source.Nachname),
    Country: country,
    Zip: cleanStringStage1(source.Postleitzahl),
    Phone: phoneResult.phone,
    sonderfall: phoneResult.sonderfall
  };

  // Stufe 2 (ehemals If-Node, true-Zweig)
  if (row.sonderfall === true) {
    row.Phone = normalizePhoneStage2(row.Phone, row.Country);
  }

  // sonderfall wird nicht ausgegeben
  return CSV_COLUMNS.map(column => csvField(row[column])).join(',');
});

return [{ json: { csv: zeilen.join('\n') } }];
